import React from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";
import "../styles/Search.css";

const GigBoard = () => {
  const [selectedFilter, setFilter] = useState("keyword");
  const [keywords, setKeywords] = useState("");
  const [gigs, setGigs] = useState([]);
  const navigate = useNavigate();

  const getGigs = async () => {
    try {
      let params = {};
      switch (selectedFilter) {
        case "keyword":
          params.keyword = keywords;
          break;
        case "username":
          params.username = keywords;
          break;
        case "genre":
          params.genre = keywords;
          break;
        case "city":
          params.city = keywords;
          break;
        default:
          break;
      }

      const token = localStorage.getItem("token");

      const response = await axios.get("http://localhost:5000/api/gigs/search", {
        headers: { Authorization: `Bearer ${token}` },
        params: params,
      });

      setGigs(response.data);
    } catch (error) {
      console.error("Error fetching gigs:", error);
      setGigs([]);
    }
  };

  const viewPosting = (gig) => {
    navigate(`/gig/${gig._id}`);
  };

  useEffect(() => {
    getGigs();
  }, []);

  return (
    <div className="search-container">
      <h2 className="profile-title">GIG BOARD</h2>
      <p className="search-filter-label">Please select a search filter.</p>
      <div className="search-bar">
        <input
          type="text"
          placeholder="keywords here..."
          onChange={(e) => setKeywords(e.target.value)}
        />
        <button className="search-btn" onClick={getGigs}>Search</button>
      </div>
      <div className="filter-buttons">
        <button className="filter-btn" onClick={() => setFilter("keyword")}>Keyword</button>
        <button className="filter-btn" onClick={() => setFilter("username")}>Username</button>
        <button className="filter-btn" onClick={() => setFilter("genre")}>Genre</button>
        <button className="filter-btn" onClick={() => setFilter("city")}>City</button>
      </div>
      <p>Searching by <b>{selectedFilter}</b></p>

      <div className="card-container">
        {gigs.map((gig) => (
          <div key={gig._id} className="gig-card">
            <h3 className="gig-title">{gig.title}</h3>
            <p className="gig-username">{gig.username}</p>
            <p className="gig-type">{gig.gigType}</p>
            <p className="gig-genre">{gig.genre?.join(", ")}</p>
            <p className="gig-city">{gig.city}</p>
            <p className="gig-description">{gig.description}</p>
            <p className="gig-expiry">Expires: {gig.expiryDate?.split('T')[0]}</p>
            <button className="view-posting-btn" onClick={() => viewPosting(gig)}>
              View Posting
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default GigBoard;
